#include <bits/stdc++.h>
using namespace std;
int M(int p,int q){int v=min(16,p*q);if(min(p,q)==3&&max(p,q)>=5&&max(p,q)<=7)v=min(v,max(p,q)+8);return v;}
int quota(int w){return w%2 ? max((w-1)&-(w-1),(w+1)&-(w+1))-1 : (w&-w)-1;}
map<string,int> cache;
int opt(int w, vector<int> hs,int ell,bool q=true){int c=w/2,b=w*(w-1)/2,r=min((int)hs.size(),quota(w));if(!q)r=hs.size();int bm=min(b,c*(int)hs.size());string k; k+=char(w);k+=char(ell);k+=char(q);for(int h:hs)k+=char(h);auto it=cache.find(k);if(it!=cache.end())return it->second;vector<int>dp((bm+1)*(r+1),-999999),ndp(dp.size());dp[0]=0;int lim=0,proc=0;for(int h:hs){fill(ndp.begin(),ndp.end(),-999999);for(int u=0;u<=lim;u++)for(int t=0;t<=min(proc,r);t++){int score=dp[u*(r+1)+t];if(score<0&&score==-999999)continue;for(int x=0;x<=min(c,bm-u);x++){int tt=t+(x==c);if(tt>r)continue;ndp[(u+x)*(r+1)+tt]=max(ndp[(u+x)*(r+1)+tt],score+2*M(x,h)-ell*x);}}dp.swap(ndp);lim=min(bm,lim+c);proc++;}int out=ell*b+*max_element(dp.begin(),dp.end());cache[k]=out;return out;}
vector<int> weights;long long counts[33][20],killed[33][20];int maxbound[33][20];vector<int> argmax[33][20];ofstream surv;
int bound(bool q=true){int best=INT_MAX;for(int ell: {2,3,1,4,0,5,6,7,8,9}){vector<int>hs;for(int w:weights)if(w/2>ell)hs.push_back(w/2);int B=0;for(int i=0;i<(int)hs.size();i++)for(int j=0;j<i;j++)B+=2*M(hs[i],hs[j]);for(int w:weights)if(w/2<=ell)B+=opt(w,hs,ell,q);int ls=0,lm=0;for(int w:weights)if(w/2>ell){auto ns=hs;ns.erase(find(ns.begin(),ns.end(),w/2));int base=0;for(int h:ns)base+=M(w/2,h);int loss=base-opt(w,ns,0,q)/2;ls+=loss;lm=max(lm,loss);}B-=2*max(lm,(ls+1)/2);best=min(best,B);if(best<992)break;}return best;}
void rec(int left,int sum,int last){if(!left){if(sum)return;int s=weights.size(),m=weights[0];counts[s][m]++;int b=bound();if(b<992)killed[s][m]++;else{surv<<s<<" "<<m<<" "<<b;for(int w:weights)surv<<" "<<w;surv<<"\n";}if(b>maxbound[s][m]){maxbound[s][m]=b;argmax[s][m]=weights;}return;}if(sum<left*2||sum>left*last)return;for(int w=min(last,sum-2*(left-1));w>=2&&w*left>=sum;w--){weights.push_back(w);rec(left-1,sum-w,w);weights.pop_back();}}
int main(int argc,char**argv){int low=argc>1?stoi(argv[1]):20,hi=argc>2?stoi(argv[2]):32;surv.open(argc>3?argv[3]:"survivors.txt");for(int s=hi;s>=low;s--){rec(s,93,18);for(int m=2;m<=18;m++)if(counts[s][m]){cout<<"{\"support\":"<<s<<",\"maximum\":"<<m<<",\"profiles\":"<<counts[s][m]<<",\"excluded\":"<<killed[s][m]<<",\"max_bound_doubled\":"<<maxbound[s][m]<<",\"witness\":[";for(int i=0;i<s;i++){if(i)cout<<',';cout<<argmax[s][m][i];}cout<<"]}"<<endl;}cerr<<"s="<<s<<" cache="<<cache.size()<<endl;}}
